<?php
namespace App\Http\Controllers;
use App\Models\Customer;use App\Models\Order;use App\Models\OrderItem;use App\Models\Products;use App\Models\StockMovement;use Illuminate\Http\Request;use Illuminate\Support\Facades\DB;
class OrderController extends Controller {private function manager(Request $r):void{abort_unless($r->user()?->isManager(),403);}public function index(Request $r){$this->manager($r);$orders=Order::with('customer')->when($r->q,fn($q,$term)=>$q->where('order_number','like','%'.$term.'%')->orWhereHas('customer',fn($c)=>$c->where('name','like','%'.$term.'%')))->orderByDesc('id')->paginate(15)->withQueryString();return view('orders.index',compact('orders'));}public function create(Request $r){$this->manager($r);$customers=Customer::where('status','active')->orderBy('name')->get();$products=Products::where('is_active',true)->where('stock_quantity','>',0)->orderBy('product_name')->get();return view('orders.create',compact('customers','products'));}public function store(Request $r){$this->manager($r);$data=$r->validate(['customer_id'=>'nullable|exists:customers,id','order_date'=>'required|date','delivery_address'=>'nullable|string|max:2000','discount_amount'=>'nullable|numeric|min:0','tax_amount'=>'nullable|numeric|min:0','notes'=>'nullable|string|max:2000','items'=>'required|array|min:1','items.*.product_id'=>'required|distinct|exists:products,id','items.*.quantity'=>'required|integer|min:1']);$order=DB::transaction(function()use($data,$r){$order=Order::create(['order_number'=>'SO-'.now()->format('YmdHis').'-'.strtoupper(substr(bin2hex(random_bytes(3)),0,6)),'customer_id'=>$data['customer_id']??null,'created_by'=>$r->user()->id,'status'=>'confirmed','payment_status'=>'unpaid','delivery_status'=>'pending','order_date'=>$data['order_date'],'delivery_address'=>$data['delivery_address']??null,'discount_amount'=>$data['discount_amount']??0,'tax_amount'=>$data['tax_amount']??0,'notes'=>$data['notes']??null]);$subtotal=0;foreach($data['items'] as $row){$product=Products::lockForUpdate()->findOrFail($row['product_id']);if($row['quantity']>$product->stock_quantity)abort(422,'Insufficient stock for '.$product->product_name.'.');$line=$row['quantity']*(float)$product->product_price;$subtotal+=$line;$before=$product->stock_quantity;$product->decrement('stock_quantity',$row['quantity']);$after=$product->fresh()->stock_quantity;OrderItem::create(['order_id'=>$order->id,'product_id'=>$product->id,'quantity'=>$row['quantity'],'unit_price'=>$product->product_price,'line_total'=>$line]);StockMovement::create(['product_id'=>$product->id,'user_id'=>$r->user()->id,'type'=>'STOCK_OUT','quantity'=>$row['quantity'],'balance_before'=>$before,'balance_after'=>$after,'reason'=>'Sales order '.$order->order_number]);}$order->update(['subtotal'=>$subtotal,'total_amount'=>$subtotal+(float)$order->tax_amount-(float)$order->discount_amount]);return $order;});return redirect()->route('orders.show',$order)->with('success','Sales order created and stock reserved.');}public function show(Request $r,Order $order){$this->manager($r);$order->load(['customer','creator','items.product']);return view('orders.show',compact('order'));}public function updateStatus(Request $r,Order $order){$this->manager($r);$data=$r->validate(['delivery_status'=>'required|in:pending,processing,shipped,delivered,cancelled','payment_status'=>'required|in:unpaid,partial,paid,refunded']);$order->update($data+['delivered_date'=>$data['delivery_status']==='delivered'?now()->toDateString():$order->delivered_date]);return back()->with('success','Order status updated.');}}
